import { Color } from '../../mol-util/color/index.js';
import { ParamDefinition as PD } from '../../mol-util/param-definition.js';
import { getPaletteParams, getPalette } from '../../mol-util/color/palette.js';
import { ColorLists, getColorListFromName } from '../../mol-util/color/lists.js';
import { ColorThemeCategory } from './categories.js';
import { Particle } from '../../mol-model/particles/particle-list.js';
const DefaultList = 'dark-2';
const DefaultColor = Color(0xCCCCCC);
const Description = 'Gives every particle a unique color based on its index in the particle list.';
export const ParticleIndexColorThemeParams = {
    ...getPaletteParams({ type: 'colors', colorList: DefaultList }),
};
function getParticleList(ctx) {
    if (ctx.particles)
        return ctx.particles;
    return undefined;
}
export function getParticleIndexColorThemeParams(ctx) {
    const params = PD.clone(ParticleIndexColorThemeParams);
    const particles = getParticleList(ctx);
    if (particles) {
        const { count } = particles;
        if (count > ColorLists[DefaultList].list.length) {
            params.palette.defaultValue.name = 'colors';
            params.palette.defaultValue.params = {
                ...params.palette.defaultValue.params,
                list: { kind: 'interpolate', colors: getColorListFromName(DefaultList).list }
            };
        }
    }
    return params;
}
export function ParticleIndexColorTheme(ctx, props) {
    let color;
    let legend;
    const particles = getParticleList(ctx);
    if (particles) {
        const { count } = particles;
        const palette = getPalette(count, props);
        legend = palette.legend;
        const pick = (index) => index >= 0 && index < count ? palette.color(index) : DefaultColor;
        color = (location) => {
            if (Particle.isLocation(location)) {
                return pick(location.index);
            }
            return DefaultColor;
        };
    }
    else {
        color = () => DefaultColor;
    }
    return {
        factory: ParticleIndexColorTheme,
        granularity: 'instance',
        color,
        props,
        description: Description,
        legend
    };
}
export const ParticleIndexColorThemeProvider = {
    name: 'particle-index',
    label: 'Particle Index',
    category: ColorThemeCategory.Particle,
    factory: ParticleIndexColorTheme,
    getParams: getParticleIndexColorThemeParams,
    defaultValues: PD.getDefaultValues(ParticleIndexColorThemeParams),
    isApplicable: (ctx) => !!getParticleList(ctx)
};
